static func find_targets(from: Node, target: String, activator: Node) -> Array[Node]:
    match target:
        "!self":
            return [from.get_parent() if from is GodotTrenchOutput else from]
        "!activator", "!caller":
            return [activator] if activator else []
        "!player":
            var player := from.get_tree().get_first_node_in_group(&"player")
            return [player] if player else []
    if target.begins_with("@"):
        return from.get_tree().get_nodes_in_group(StringName(target.substr(1)))
    if target.begins_with("/"):
        var node := from.get_node_or_null(NodePath(target))
        return [node] if node else []
    var named := _named_nodes(lookup_root(from))   # targetname cache
    if target.ends_with("*"):
        var prefix := target.trim_suffix("*")
        # ... collect every named[key] whose key begins_with(prefix)
    return named.get(target, [])

